import pandas as pd
import re

def parse_composition(comp_str):
    elements = re.findall(r'([A-Z][a-z]*)([0-9]*\.[0-9]+|[0-9]*)', comp_str)
    comp_dict = {}
    for el, amt in elements:
        if amt == '':
            amt = 1.0
        else:
            amt = float(amt)
        comp_dict[el] = comp_dict.get(el, 0) + amt

    total = sum(comp_dict.values())
    for el in comp_dict:
        comp_dict[el] /= total
    return comp_dict

df = pd.read_csv('b3_supercon_target.csv')
features = []
for comp in df['composition']:
    features.append(parse_composition(comp))

df_feat = pd.DataFrame(features).fillna(0)
df_feat['target'] = df['target']
df_feat.to_csv('parsed_features.csv', index=False)
print("Data parsed successfully. Columns:", df_feat.columns.tolist())

