comp_B = {'Y': 0.6, 'Ca': 0.4, 'Ba': 1.2, 'La': 0.8, 'Cu': 3, 'O': 7.15}

frac_A = {k: v / A_total for k, v in comp_A.items()}
frac_B = {k: v / B_total for k, v in comp_B.items()}

final_comp = {}
elements_to_optimize = ['O', 'Cu', 'Ba', 'Sr', 'Y', 'Ca', 'La', 'Bi', 'Fe', 'Nb', 
                        'C', 'Pr', 'As', 'B', 'Pb', 'Ce', 'Mo', 'V', 'Zn', 'Ni']

for el in elements_to_optimize:
    final_comp[el] = w_A * frac_A.get(el, 0) + w_B * frac_B.get(el, 0)

print("Sum:", sum(final_comp.values()))

out = []
for el in elements_to_optimize:
    out.append(f"{el}={final_comp[el]:.6f}")
print("Final: " + ", ".join(out))

